scripts:
(function(){
  function css(v){ return getComputedStyle(document.documentElement).getPropertyValue(v).trim(); }
  var ns = 'http://www.w3.org/2000/svg';
  function el(tag, attrs){ var e=document.createElementNS(ns,tag); for(var k in attrs) e.setAttribute(k, attrs[k]); return e; }

  (function(){
    var svg = document.getElementById('chart-compare');
    if(!svg) return;
    var data = [
      {l:'시장 요구\\n(9% 할인율)', v:12.3, color:css('--blue')},
      {l:'5년 FCF\\nCAGR', v:17.4, color:css('--good')},
      {l:'3년 FCF\\nCAGR', v:17.6, color:css('--good')},
      {l:'5년 매출\\nCAGR', v:14.8, color:css('--gold')},
      {l:'최근 2분기\\n매출성장', v:12.0, color:css('--risk')}
    ];
    var W=640,H=260,padL=30,padR=14,padT=20,padB=48;
    var plotW=W-padL-padR, plotH=H-padT-padB;
    var n=data.length, gap=26;
    var barW=(plotW-gap*(n-1))/n;
    var max=20;
    svg.appendChild(el('line',{x1:padL,y1:H-padB,x2:W-padR,y2:H-padB,stroke:css('--line'),'stroke-width':1}));
    [5,10,15,20].forEach(function(gv){
      var y = H-padB-(gv/max)*plotH;
      svg.appendChild(el('line',{x1:padL,y1:y,x2:W-padR,y2:y,stroke:css('--line'),'stroke-width':1,'stroke-dasharray':'3,4'}));
      var t=el('text',{x:padL-6,y:y+3,'text-anchor':'end','font-size':9.5,'font-family':'IBM Plex Mono, monospace',fill:css('--ink-soft')});
      t.textContent=gv+'%'; svg.appendChild(t);
    });
    data.forEach(function(d,i){
      var x = padL + i*(barW+gap);
      var bh = (d.v/max)*plotH;
      var y = H-padB-bh;
      svg.appendChild(el('rect',{x:x,y:y,width:barW,height:bh,rx:4,fill:d.color}));
      var vt = el('text',{x:x+barW/2,y:y-8,'text-anchor':'middle','font-size':13,'font-family':'IBM Plex Mono, monospace',fill:css('--ink'),'font-weight':'600'});
      vt.textContent = d.v.toFixed(1)+'%';
      svg.appendChild(vt);
      var lines = d.l.split('\\n');
      lines.forEach(function(ln, li){
        var lt = el('text',{x:x+barW/2,y:H-padB+16+li*13,'text-anchor':'middle','font-size':10.5,'font-family':'IBM Plex Sans, sans-serif',fill:css('--ink-soft')});
        lt.textContent = ln;
        svg.appendChild(lt);
      });
    });
  })();
})();
